  $("metrics").innerHTML=`Game <b>${game.id}</b> · ${game.rows}×${game.cols} · ${game.mines} mines · seed <b>${game.seed}</b> · tools from head <b>#${game.toolHead}</b> · retries <b>${game.allowRetry?"allowed":"no"}</b><br>
