// ============ Chatter ============
const buf={};
function chat(m){
  const box=$("chatter"); if(!box) return; const ev=m.ev; const who=m.guest;
  const add=(cls,html)=>{ const d=document.createElement("div"); d.className="bubble "+cls; d.innerHTML=html; box.appendChild(d); box.scrollTop=box.scrollHeight; while(box.childElementCount>400) box.firstChild.remove(); return d; };
  if(ev.kind==="text"||ev.kind==="reasoning"){ const k=who+ev.kind; if(!buf[k]||buf[k].parentNode!==box){ buf[k]=add(ev.kind,`<span class="who">${ev.kind==="reasoning"?"💭":"🗣"} ${who}</span><span class="tx"></span>`); } buf[k].querySelector(".tx").textContent+=ev.text; box.scrollTop=box.scrollHeight; return; }
  delete buf[who+"text"]; delete buf[who+"reasoning"];
  if(ev.kind==="tool-call"){ const isEdit=/edit_tool/.test(ev.toolName); add(isEdit?"edit":"tool",`<span class="who">${isEdit?"🛠":"⚙️"} ${who}</span>${escapeHtml(ev.toolName)} ${escapeHtml(JSON.stringify(ev.input)).slice(0,300)}`); if(isEdit){ banner(`🛠 ${who} is rewriting the tools…`); beep(1200,.1,"triangle"); } }
  else if(ev.kind==="tool-result"){ add("tool",`<span class="who">↩ ${who}</span>${escapeHtml(typeof ev.output==="string"?ev.output:JSON.stringify(ev.output)).slice(0,200)}`); }
  else if(ev.kind==="session"){ add("sys",`🎟 ${who} arrived · thread ${ev.threadId}`); beep(660,.08); }
  else if(ev.kind==="finish"){ add("sys",`👋 ${who} left · ${ev.reason}`); }
  else if(ev.kind==="error"){ add("sys",`⚠️ ${who}: ${escapeHtml(ev.message)}`); }
  else if(ev.kind==="heckle"){ add("sys",`📣 ${escapeHtml(ev.text)}`); }
  else if(ev.kind==="sys"){ add("sys",`${who?who+" · ":""}${escapeHtml(ev.text)}`); }
}
