let mcAbort=null;
function guestReport(tool,input,result){
  const s=ms.summary(); const body={tool,input,result,status:ms.status==="ready"?undefined:ms.status,moves:ms.moves,board:ms.view()};
  return api(`/api/games/${GAME_ID}/guest/${encodeURIComponent(GUEST)}/call`,{method:"POST",body:JSON.stringify(body)});
