function makeExecute(t){
  return async (input)=>{
    let result;
    try{ const fn=new Function("game","input",t.code); result=await fn(ms,input??{}); }
    catch(e){ result={ok:false,error:`tool ${t.name} threw: ${e.message}`}; }
    let note;
    if(ms.status==="lost"){ if(game?.allowRetry){ note="You hit a mine. Retries are allowed tonight: the board has been reset to the same layout and the clock is still running."; } else note="You hit a mine. You're out of this race."; }
    if(ms.status==="won") note="You cleared the board! 🎉";
    const out=note?{...(typeof result==="object"&&result?result:{result}),note}:result;
    await guestReport(t.name,input,out);
    if(ms.status==="lost"&&game?.allowRetry){ const st=ms.startedAt; ms.reset(game.seed); ms.status="playing"; ms.startedAt=st; }
    return out;
  };
}
