      const out=r.error?{ok:false,error:r.error}:{ok:true,saved:r.name,memoId:r.memoId,note:"Tool is live now for you and every future guest. Tools list changed; fetch tools again."};
      await guestReport("edit_tool",input,out); return out; }}];
  let n=0;
